  function guardada() { try { var v = W.localStorage.getItem("ipr_lingua"); return v ? JSON.parse(v) : ""; } catch (e) { return ""; } }
  function montar() {
    var L = W.__iprLingua, T = W.__ipr73c;
    if (!L || !L.dic || !T || !T.dic) return false;
    if (!L.dic.es) L.dic.es = L62ES;
    ["pt", "en"].forEach(function (k) { if (L.dic[k] && !L.dic[k].es) L.dic[k].es = "Español"; });
    if (!EN) EN = Object.assign({}, T.dic);
    montado = true; return true;
  }
  function usarDic(es) {
    var T = W.__ipr73c, d = T.dic;
    Object.keys(EN).forEach(function (k) { if (!(k in d)) d[k] = EN[k]; });
    Object.keys(d).forEach(function (k) {
      if (es) { d[k] = Object.prototype.hasOwnProperty.call(ES, k) ? ES[k] : k; if (!(k in EN)) EN[k] = d[k]; }
      else if (k in EN) d[k] = EN[k];
    });
    if (es) Object.keys(ES).forEach(function (k) { d[k] = ES[k]; });
  }
  var aMudar = false;
  function aplicar() {
    if (!montar() || aMudar) return;
    var es = W.IPR_LINGUA === "es", T = W.__ipr73c;
    aMudar = true;
    try {
      var l = W.IPR_LINGUA; W.IPR_LINGUA = "pt"; T.aplicar();
      usarDic(es); W.IPR_LINGUA = l; T.aplicar();
      if (es) D.documentElement.lang = "es";
    } finally { aMudar = false; }
  }
  function arrancar() {
    if (!montar()) return setTimeout(arrancar, 300);
    var g = guardada();
    if (g === "es" || (!g && String(W.IPR_LANG || "").toLowerCase() === "es")) { W.IPR_LINGUA = "es"; }
    aplicar();
    try { D.dispatchEvent(new CustomEvent("ipr:lingua", { detail: W.IPR_LINGUA })); } catch (e) {}
  }
  D.addEventListener("ipr:lingua", function () { setTimeout(aplicar, 0); });
  if (D.readyState === "loading") D.addEventListener("DOMContentLoaded", function () { setTimeout(arrancar, 50); }); else setTimeout(arrancar, 50);
